// @generated by:gauntlet run:godseye-local-recovery
import { randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { recoveryCommitments } from "../packages/core/src/recovery-capacity.js";
import {
  type RecoveryFixture,
  recoveryFixture,
  requireRecoveryFixture,
} from "./recovery-helpers.js";

describe("durable physical recovery uncertainty and controller reconstruction", () => {
  let fixture: RecoveryFixture;
  beforeEach(async () => {
    fixture = await recoveryFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  async function restore() {
    const { backup } = await fixture.backup();
    const preparation = await fixture.prepareRestore(backup.id);
    const run = await fixture.admitRecovery(preparation);
    return { preparation, run };
  }
  const state = async (id: string) =>
    (await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs.find(
      (item) => item.id === id,
    );

  it("T-AC-41 reconciles a lost restore acknowledgment after reconstruction without repeating physical effects", async () => {
    const { preparation, run } = await restore(),
      source = structuredClone(fixture.provider.resources.get(fixture.source.id));
    fixture.recoveryProvider.lostAcknowledgments.add("restore");
    await fixture.infrastructure.foundation.tick("lost-restore-receipt-worker");
    expect(await state(run.id)).toMatchObject({ state: "unknown", recoveryHold: true });
    const effects = structuredClone(fixture.recoveryProvider.effects),
      target = structuredClone(fixture.recoveryProvider.resources.get(preparation.id));
    expect(
      (await recoveryCommitments(fixture.store.db)).reduce((sum, item) => sum + item.storageGiB, 0),
    ).toBeGreaterThanOrEqual(10);
    const restarted = new InfrastructureEngine(fixture.store, fixture.configuration);
    await restarted.foundation.reconcile(fixture.freshOwner(), run.runId, randomUUID());
    expect(
      (await restarted.recovery.overview(fixture.freshOwner())).runs.find(
        (item) => item.id === run.id,
      ),
    ).toMatchObject({ state: "restore-verified", recoveryHold: true });
    expect(fixture.recoveryProvider.effects).toEqual(effects);
    expect(fixture.recoveryProvider.resources.get(preparation.id)).toEqual(target);
    expect(fixture.provider.resources.get(fixture.source.id)).toEqual(source);
  });

  it("T-AC-41 treats disconnected absence as unknown and retains all exact capacity obligations", async () => {
    const { preparation, run } = await restore();
    fixture.recoveryProvider.beforeAction = async (action) => {
      if (action === "restore") throw new Error("Fixture disconnected before receipt");
    };
    await fixture.infrastructure.foundation.tick("disconnected-restore-worker");
    const commitments = await recoveryCommitments(fixture.store.db);
    fixture.recoveryProvider.beforeAction = undefined;
    await fixture.infrastructure.foundation.reconcile(
      fixture.freshOwner(),
      run.runId,
      randomUUID(),
    );
    expect(await state(run.id)).toMatchObject({ state: "unknown", recoveryHold: true });
    expect(await recoveryCommitments(fixture.store.db)).toEqual(commitments);
    expect(fixture.recoveryProvider.resources.has(preparation.id)).toBe(false);
    expect(
      fixture.recoveryProvider.effects.filter((effect) => effect.action === "restore"),
    ).toEqual([]);
    expect(await fixture.infrastructure.foundation.tick("unsafe-repeat-restore-worker")).toBe(
      false,
    );
  });

  it.each(["cancel", "epoch", "generation"] as const)(
    "T-AC-41 blocks %s drift immediately before awaited restore dispatch",
    async (mode) => {
      const { preparation, run } = await restore();
      fixture.recoveryProvider.beforeAction = async (action) => {
        if (action !== "restore") return;
        if (mode === "cancel")
          await fixture.infrastructure.foundation.cancel(
            fixture.freshOwner(),
            run.runId,
            randomUUID(),
          );
        if (mode === "epoch")
          await fixture.infrastructure.foundation.advanceEpoch(
            fixture.freshOwner(),
            fixture.development.id,
            randomUUID(),
          );
        if (mode === "generation")
          fixture.recoveryProvider.binding.generation = "foreign-replacement-generation";
      };
      await fixture.infrastructure.foundation.tick("restore-dispatch-drift-worker");
      expect(fixture.recoveryProvider.resources.has(preparation.id)).toBe(false);
      expect((await state(run.id))?.state).not.toBe("restore-verified");
      expect((await recoveryCommitments(fixture.store.db)).length).toBeGreaterThanOrEqual(2);
    },
  );

  it.each(["cancel", "epoch", "generation"] as const)(
    "T-AC-41 retains a late materialized target after %s authority loss",
    async (mode) => {
      const { preparation, run } = await restore();
      fixture.recoveryProvider.afterAction = async (action) => {
        if (action !== "restore") return;
        if (mode === "cancel")
          await fixture.infrastructure.foundation.cancel(
            fixture.freshOwner(),
            run.runId,
            randomUUID(),
          );
        if (mode === "epoch")
          await fixture.infrastructure.foundation.advanceEpoch(
            fixture.freshOwner(),
            fixture.development.id,
            randomUUID(),
          );
        if (mode === "generation")
          fixture.recoveryProvider.binding.generation = "late-replacement-generation";
      };
      await fixture.infrastructure.foundation.tick("late-restore-worker");
      expect(fixture.recoveryProvider.resources.has(preparation.id)).toBe(true);
      expect(await state(run.id)).toMatchObject({ state: "unknown", recoveryHold: true });
      expect((await recoveryCommitments(fixture.store.db)).length).toBeGreaterThanOrEqual(2);
      expect(
        await fixture.infrastructure.foundation.tick("never-overwrite-late-target-worker"),
      ).toBe(false);
      expect(
        fixture.recoveryProvider.effects.filter((effect) => effect.action === "restore"),
      ).toHaveLength(1);
    },
  );

  it.each(["scope", "wal-gap", "manifest", "foreign-target", "not-paused"])(
    "T-AC-41 preserves target and source when %s inspection cannot prove safe recovery",
    async (mode) => {
      const { preparation, run } = await restore(),
        source = structuredClone(fixture.provider.resources.get(fixture.source.id));
      fixture.recoveryProvider.inspectionResult = (result) => {
        if (mode === "scope") result.scopeHash = "f".repeat(64);
        if (mode === "wal-gap") result.metadata.archiveContinuous = false;
        if (mode === "manifest") result.metadata.manifestHash = "f".repeat(64);
        if (mode === "foreign-target")
          requireRecoveryFixture(result.destination).allocationId = randomUUID();
        if (mode === "not-paused")
          Object.assign(requireRecoveryFixture(result.destination), { replayPaused: false });
        return result;
      };
      await fixture.infrastructure.foundation.tick("bad-restore-inspection-worker");
      expect(await state(run.id)).toMatchObject({ state: "unknown", recoveryHold: true });
      expect(fixture.recoveryProvider.resources.has(preparation.id)).toBe(true);
      expect(fixture.provider.resources.get(fixture.source.id)).toEqual(source);
      expect((await recoveryCommitments(fixture.store.db)).length).toBeGreaterThanOrEqual(2);
      expect(
        (
          await fixture.infrastructure.recovery.assessActivation(
            fixture.freshOwner(),
            preparation.environmentId,
          )
        ).activation,
      ).toBe("blocked");
    },
  );

  it("T-AC-40 never substitutes an empty, missing or truncated Foundation journal for complete business-effect coverage", async () => {
    const { preparation } = await restore();
    await fixture.infrastructure.foundation.tick("restored-data-only-worker");
    await fixture.store.db.delete(schema.effects);
    const restarted = new InfrastructureEngine(fixture.store, fixture.configuration);
    const empty = await restarted.recovery.assessActivation(
      fixture.freshOwner(),
      preparation.environmentId,
    );
    expect(empty).toMatchObject({ activation: "blocked", recoveryHold: true });
    expect(empty.reasons).toContain("NON_REWOUND_BUSINESS_EFFECT_COVERAGE_UNQUALIFIED");
  });

  it("T-AC-41 never expires unresolved recovery effects even when a terminal timestamp was written before a late outcome", async () => {
    const { run } = await restore();
    fixture.recoveryProvider.lostAcknowledgments.add("restore");
    await fixture.infrastructure.foundation.tick("unresolved-recovery-retention-worker");
    const old = new Date(fixture.clock.now().getTime() - 100 * 86_400_000);
    await fixture.store.db
      .update(schema.executionRuns)
      .set({ terminalAt: old })
      .where(eq(schema.executionRuns.id, run.runId));
    await fixture.store.db
      .update(schema.effects)
      .set({ updatedAt: old })
      .where(eq(schema.effects.runId, run.runId));
    await fixture.infrastructure.foundation.prune(fixture.freshOwner());
    expect(
      await fixture.store.db
        .select()
        .from(schema.effects)
        .where(eq(schema.effects.runId, run.runId)),
    ).toHaveLength(1);
    expect(await state(run.id)).toMatchObject({ state: "unknown", recoveryHold: true });
    expect((await recoveryCommitments(fixture.store.db)).length).toBeGreaterThanOrEqual(2);
  });
});
